    flg = 0
    if len(word) == 1:
        flg = 1
    for i in range(2, len(word)):
        if len(word)%i == 0:
            flg = 1
    if flg == 0 or len(word) == 2:
        new_lst.append(word)
return " ".join(new_lst)

